# Analyze the pattern more carefully - it seems like we need to apply a transformation
# Let me understand what the pattern is and compute the correct output

def compute_output_grid(grid):
    """Compute output grid based on detected pattern."""
    h = len(grid)
    w = len(grid[0])

    output = [[0]*w for _ in range(h)]

    # Based on analysis, the pattern seems to depend on whether row or col is multiple of 5
    for r in range(h):
        for c in range(w):
            row_mod = r % 5
            col_mod = c % 5

            if row_mod == 0 and col_mod == 0:
                output[r][c] = 6  # Both mod 0
            elif row_mod == 0 or col_mod == 0:
                output[r][c] = 4  # One is mod 0
            else:
                output[r][c] = grid[r][c]  # Keep original (3s)

    return output

output = compute_output_grid(None)
print("Output grid:")
for row in output:
    print(' '.join(str(x) for x in row))

# New hypothesis: Output shows only the deviation markers clearly
# Non-anchor cells become 3 (background), anchor cells show simplified pattern

def compute_output_grid_v2(grid):
    h = len(grid)
    w = len(grid[0])

    output = [[0]*w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            # Only keep anchors at columns divisible by 5
            if c % 5 == 0:
                # Apply simple pattern: depends on row mod 5 and col mod 5
                row_mod = r % 5
                col_mod = c // 5  # which anchor column (0-4)

                # Simplest pattern: fill whole rows/sections
                if row_mod < 2:
                    val = 4  # First two "rows" of section
                elif row_mod == 2:
                    val = 6
                else:
                    val = 7  # Last two "rows" of section
                output[r][c] = val
            else:
                # Non-anchor becomes 3
                output[r][c] = 3

    return output

output = compute_output_grid_v2(grid)
print("Output grid v2:")
for i, row in enumerate(output):
    print(f"Row {i}: {' '.join(str(x) for x in row)}")

